function getDefaultConfig() {
  return {
    version: 1,
    trainingTypes: DEFAULT_TRAINING_TYPES,
    exercises: DEFAULT_EXERCISES,
    muscles: DEFAULT_MUSCLES,
    statistics: [DEFAULT_COUNT_STAT, DEFAULT_VOLUME_STAT, DEFAULT_1RM_STAT],
    plans: DEFAULT_PLANS
  };
}

// src/data/configMigrate.ts
function migrateConfig(config) {
  if (!config.version)
    config.version = 1;
  if (!config.trainingTypes)
    config.trainingTypes = getDefaultConfig().trainingTypes;
  if (!config.exercises)
    config.exercises = getDefaultConfig().exercises;
  if (!config.muscles)
    config.muscles = getDefaultConfig().muscles;
  if (!config.statistics) {
    config.statistics = config.trainingTypes.map((type) => ({
      id: `seed-total-sets-${type.id}`,
      name: "\u603B\u7EC4\u6570",
      associatedTypes: [type.id],
      formula: { mode: "builder", builder: { kind: "count" } },
      granularity: "daily",
      enabled: true
    }));
  }
  if (!config.plans)
    config.plans = [];
  {
    const seed = getDefaultConfig();
    const exIds = new Set(config.exercises.map((e) => e.id));
    for (const ex of seed.exercises)
      if (!exIds.has(ex.id))
        config.exercises.push(ex);
    const planNames = new Set(config.plans.map((p) => p.name));
    for (const pl of seed.plans ?? [])
      if (!planNames.has(pl.name))
        config.plans.push(pl);
    const statIds = new Set(config.statistics.map((s) => s.id));
    for (const st of seed.statistics)
      if (!statIds.has(st.id))
        config.statistics.push(st);
  }
  const migrateUnit = (fields) => {
    if (!fields)
      return;
    for (const f of fields) {
      if (!f)
        continue;
      if (f.unit === "mass")
        f.mass = true;
      else if (f.unit === "custom")
        f.unitLabel = f.customUnit ?? "";
      else if (f.unit === "count")
        f.unitLabel = "\u6B21";
      delete f.unit;
      delete f.customUnit;
    }
  };
  for (const type of config.trainingTypes ?? [])
    migrateUnit(type.fields);
  return applyDefaultNameKeys(config);
}

