async function main() {
  const argv = process.argv.slice(2);
  const command = argv[0];
  if (!command || command === "help" || command === "--help" || command === "-h") {
    process.stdout.write(HELP);
    return;
  }
  const args = parseArgs(argv.slice(1), {
    flags: ["json", "all", "yes", "clear-muscles", "no-ask", "force"],
    repeated: ["field", "param", "muscle"]
  });
  if (command === "capabilities") {
    cmdCapabilities();
    return;
  }
  const vaultPath = args.options["vault"] || process.env["WORKOUT_VAULT"] || "";
  if (!vaultPath) {
    throw new UsageError("\u7F3A\u5C11 vault \u5B9A\u4F4D\uFF1A\u8BF7\u52A0 --vault <\u4ED3\u5E93\u6839\u76EE\u5F55> \u6216\u8BBE\u7F6E\u73AF\u5883\u53D8\u91CF WORKOUT_VAULT");
  }
  const env = await loadEnv(vaultPath, { allowNonVault: args.flags.has("force") });
  switch (command) {
    case "locate":
      return cmdLocate(env, args);
    case "config":
      return cmdConfig(env, args);
    case "resolve":
      return cmdResolve(env, args);
    case "add":
      return cmdAdd(env, args);
    case "list":
      return cmdList(env, args);
    case "delete":
      return cmdDelete(env, args);
    case "compact":
      return cmdCompact(env, args);
    case "stats":
      return cmdStats(env, args);
    case "plan":
      return cmdPlan(env, args);
    case "block":
      return cmdBlock(env, args);
    case "doctor":
      return cmdDoctor(env, args);
    case "query":
      return cmdQuery(env, args);
    default:
      throw new UsageError(`\u672A\u77E5\u547D\u4EE4 "${command}"\u3002\u8FD0\u884C workout-cli help \u67E5\u770B\u5168\u90E8\u547D\u4EE4\u3002`);
  }
}
main().catch((e) => {
  if (e instanceof UsageError) {
    process.stderr.write(`\u7528\u6CD5\u9519\u8BEF\uFF1A${e.message}
`);
    process.exit(2);
  }
  if (e instanceof CliError) {
    process.stderr.write(`\u9519\u8BEF\uFF1A${e.message}
`);
    process.exit(1);
  }
  process.stderr.write(`\u672A\u9884\u671F\u7684\u9519\u8BEF\uFF1A${e instanceof Error ? e.stack ?? e.message : String(e)}
`);
  process.exit(1);
});
